recipes.code:
{
  "inputs": [
    {
      "id": "kudosity-api-key",
      "type": "promptString",
      "description": "Your Kudosity API key (Settings → API Settings).",
      "password": true
    },
    {
      "id": "kudosity-api-secret",
      "type": "promptString",
      "description": "Your Kudosity API secret. Required only for contact-list and balance tools.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "kudosity-mcp@0.5.0"
      ],
      "env": {
        "KUDOSITY_API_KEY": "${input:kudosity-api-key}",
        "KUDOSITY_API_SECRET": "${input:kudosity-api-secret}"
      }
    }
  }
}
